#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sorted_and_unique() {
        assert!(ROWS.windows(2).all(|w| w[0].key < w[1].key));
        let mut idx: Vec<u16> = ROWS.iter().map(|r| r.index).collect();
        idx.sort_unstable();
        idx.dedup();
        assert_eq!(idx.len(), ROWS.len(), "two rows under one record index");
    }

    fn count(g: RowGroup) -> usize {
        ROWS.iter().filter(|r| r.group == g).count()
    }

    /// The counts on build 26361232.
    #[test]
    fn pinned_counts() {
        assert_eq!(count(RowGroup::Pouch), 88);
        assert_eq!(count(RowGroup::Breakable), 15);
        assert_eq!(REFUSED.len(), 40);
    }

    /// A key is in one group at most, and a refused key in none.
    #[test]
    fn no_key_in_two_groups_and_refused_keys_absent() {
        for (k, _, _) in REFUSED {
            assert_eq!(lookup(*k), None, "refused row {k} is in the table");
        }
        // `sorted_and_unique` makes a key's group single-valued; this says it
        // in the words of the rule.
        for r in ROWS {
            assert_eq!(ROWS.iter().filter(|x| x.key == r.key).count(), 1);
        }
    }

    /// Every row has something to multiply and an entry count the dispatch
    /// write path accepts.
    #[test]
    fn rows_are_plausible() {
        for r in ROWS {
            assert!(r.item_amounts >= 2, "{r:?}");
            assert!((1..=64).contains(&r.entries), "{r:?}");
        }
    }

    #[test]
    fn spot_checks() {
        assert_eq!(lookup(400005).map(|r| r.group), Some(RowGroup::Pouch)); // DropSet_Money_Copper_100_500
        assert_eq!(lookup(400006).map(|r| r.group), Some(RowGroup::Pouch)); // DropSet_Money_Copper_10000
        assert_eq!(lookup(400007).map(|r| r.group), Some(RowGroup::Pouch)); // DropSet_Money_Copper_20000
        assert_eq!(lookup(1016612).map(|r| r.group), Some(RowGroup::Pouch)); // DropSet_Money_Copper_100000
        assert_eq!(lookup(100137).map(|r| r.group), Some(RowGroup::Pouch)); // DropSet_Pinball_Bag
        assert_eq!(lookup(100000).map(|r| r.group), Some(RowGroup::Breakable)); // DropSet_BoxBarrel_01
        assert_eq!(lookup(110000).map(|r| r.group), Some(RowGroup::Breakable)); // DropSet_BoxBarrel_02
        assert_eq!(lookup(100001).map(|r| r.group), Some(RowGroup::Breakable)); // DropSet_Pot_01
        assert_eq!(lookup(110001).map(|r| r.group), None); // DropSet_BoxBarrel_03
        assert_eq!(lookup(160100).map(|r| r.group), None); // DropSet_Arrow_Package
        assert_eq!(lookup(0), None);
        assert_eq!(lookup(u32::MAX), None);
    }

    #[test]
    fn names_are_the_log_vocabulary() {
        assert_eq!(RowGroup::Pouch.name(), "pouch");
        assert_eq!(RowGroup::Breakable.name(), "breakable");
    }
}
